function loadProfile(){let saved;try{saved=JSON.parse(localStorage.getItem(STORAGE));}catch{}if(saved?.version===2){try{return R.normalize(saved);}catch{}}try{const old=JSON.parse(localStorage.getItem('kiem-vuc-save-v1'));if(old?.started){localStorage.setItem('kiem-vuc-save-v1-backup',JSON.stringify(old));return R.migrate(old);}}catch{}return R.profile();}
function save(){G.ensure(state,dayKey());refreshStats();if(!state.started||state.demo||modal==='offline')return;Object.assign(state,{x:hero.x,y:hero.y,hp:hero.hp,mp:hero.mp,lastSave:Date.now()});try{localStorage.setItem(STORAGE,JSON.stringify(state));$('#saveStatus').textContent='Đã lưu';}catch{$('#saveStatus').textContent='Lưu bị chặn';}}
function escapeHTML(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function fmt(n){n=Number(n)||0;return n>=1e9?(n/1e9).toFixed(1)+' tỷ':n>=1e6?(n/1e6).toFixed(1)+' tr':Math.floor(n).toLocaleString('vi-VN');}
function full(n){return Math.floor(n||0).toLocaleString('vi-VN');}
